    fn html_comments_are_suppressed_across_lines_without_changing_visible_spans() {
        let input = "[before](before.md) WP-MVP-0001 <!-- fake [one](fake.md) WP-MVP-9999\n\
                     Ω [two](fake-two.md) WP-MVP-9998\n\
                     ```md\n\
