                     ``` --> [after](after.md) WP-MVP-0002\n\
                     <!-- [four](fake-four.md) --><!-- WP-MVP-9996 -->\n\
                     ```md\n\
                     <!-- [fenced](fake.md) WP-MVP-9995 -->\n\
                     ```\n\
                     [last](last.md) WP-MVP-0003\n";
        let parsed = parse(input);
        assert_eq!(
            parsed
                .links
                .iter()
                .map(|link| link.destination.as_str())
                .collect::<Vec<_>>(),
            ["before.md", "after.md", "last.md"]
